package edu.kle.permits;
import java.math.BigDecimal;
import java.time.*;
import java.nio.file.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.mock.web.MockMultipartFile;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.web.server.ResponseStatusException;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;

@SpringBootTest(properties={"spring.datasource.url=${TEST_DB_URL:jdbc:h2:mem:modern;MODE=PostgreSQL;DB_CLOSE_DELAY=-1;LOCK_TIMEOUT=15000}","spring.datasource.driver-class-name=${TEST_DB_DRIVER:org.h2.Driver}","spring.datasource.username=${TEST_DB_USER:sa}","spring.datasource.password=${TEST_DB_PASSWORD:}","app.jwt-secret=test-secret-with-at-least-thirty-two-bytes-long","app.admin-password=InitialAdminPassword!","app.admin-local-part=admin"})
@AutoConfigureMockMvc class DatabaseIntegrationTest {
 @Autowired JdbcTemplate jdbc;@Autowired Users users;@Autowired PermitService service;@Autowired MockMvc mvc;@Autowired Properties properties;@Autowired DocumentVersions documents;@Autowired PlatformTransactionManager transactions;
 AppUser applicant,department,reviewer,zoning,finance,inspector,senior;
 @BeforeEach void setup(){applicant=fixture(Role.APPLICANT);department=fixture(Role.DEPARTMENT_OFFICER);reviewer=fixture(Role.PERMIT_REVIEWER);zoning=fixture(Role.ZONING_OFFICER);finance=fixture(Role.FINANCE_OFFICER);inspector=fixture(Role.BUILDING_INSPECTOR);senior=fixture(Role.SENIOR_DEPARTMENT_OFFICER);}
 AppUser fixture(Role r){return users.save(new AppUser("Database fixture",UUID.randomUUID()+"@permitworks.com","not-used-for-login",r));}
 PermitDtos.ApplicationInput input(Long property){return new PermitDtos.ApplicationInput("Database project","Building","123 Main Street","Construction","Owner","Architect",BigDecimal.TEN,LocalDate.now().plusDays(1),"plan.pdf","NORTH","Alteration","New permit",property,new ApprovedErModel.PropertyInput("123","N","Main Street","580001","4","Residential",new BigDecimal("15.3500000"),new BigDecimal("75.1000000")));}
 Long draft(){return service.create(input(null),applicant).id();}
 void ready(Long id){service.submit(id,applicant);service.verifyDocuments(id,new PermitDtos.DocumentDecision(true,"Verified"),department);service.assign(id,new PermitDtos.AssignmentInput(AssignmentType.PERMIT_REVIEWER,reviewer.id),department);service.assign(id,new PermitDtos.AssignmentInput(AssignmentType.ZONING_OFFICER,zoning.id),department);service.review(id,ReviewType.TECHNICAL,new PermitDtos.ReviewInput(ReviewRecommendation.APPROVE,"Technical clear"),reviewer);service.review(id,ReviewType.ZONING,new PermitDtos.ReviewInput(ReviewRecommendation.APPROVE,"Zoning clear"),zoning);service.decide(id,new PermitDtos.DecisionInput("APPROVE","Approved as reviewed"),senior);}
 @Test void tenRequiredTablesHaveExactRequestedColumns(){
  Map<String,String> required=Map.of(
   "applicants","applicant_id name email phone_no address password_hash created_at updated_at",
   "applications","application_id applicant_id property_id application_type application_date work_type work_description permit_milestone reports review_type result_description decision_reason total_fee issue_date processing_time application_status created_at updated_at",
   "documents","document_id applicant_id application_id document_name upload_date version_no file_path mime_type file_size created_at",
   "properties","property_id street_number street_direction street_name zip_code ward community_area latitude longitude created_at updated_at",
   "payments","payment_id applicant_id application_id payment_status payment_date amount transaction_id created_at",
   "inspections","inspection_id application_id officer_id result remarks inspection_date reinspection_required created_at",
   "assignments","assignment_id application_id officer_id assigned_at stage is_override created_at",
   "officers","officer_id name email phone_number password_hash official_role created_at updated_at",
   "corrections","correction_id application_id officer_id requested_date resolved_date correction_description correction_status created_at",
   "registration_requests","registration_id name personal_email registration_password_hash phone_number requested_user_type description registration_status admin_remarks reviewed_at reviewed_by created_at");
  required.forEach((table,columns)->{List<String> names=jdbc.queryForList("SELECT LOWER(column_name) FROM information_schema.columns WHERE LOWER(table_schema)='public' AND LOWER(table_name)=?",String.class,table);for(String col:columns.split(" "))assertTrue(names.contains(col),table+"."+col);assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM information_schema.tables WHERE LOWER(table_schema)='public' AND LOWER(table_name)=? AND table_type='BASE TABLE'",Integer.class,table));});
 }
 @Test void profileContactsAndHashesFollowTheAuthenticationIdentity(){applicant.phoneNo="9876501234";applicant.address="Applicant contact address";users.saveAndFlush(applicant);assertEquals(applicant.passwordHash,jdbc.queryForObject("SELECT password_hash FROM applicants WHERE applicant_id=?",String.class,applicant.id));assertEquals(applicant.address,jdbc.queryForObject("SELECT address FROM applicants WHERE applicant_id=?",String.class,applicant.id));assertEquals("PERMIT_REVIEWER",jdbc.queryForObject("SELECT official_role FROM officers WHERE officer_id=?",String.class,reviewer.id));}
 @Test void propertyHasAllFieldsAndCanBeReferencedByMultipleOwnedApplications(){var first=service.get(draft(),applicant);var next=service.create(input(first.property().id()),applicant);assertEquals(first.property().id(),next.property().id());assertEquals("Main Street",next.property().streetName());assertEquals("Alteration",next.workType());assertEquals("New permit",next.applicationType());assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM applications WHERE property_id=?",Integer.class,first.property().id()));assertThrows(ResponseStatusException.class,()->service.create(input(first.property().id()),fixture(Role.APPLICANT)));}
 @Test void invalidPropertyReferenceAndApplicantReferenceAreRejected(){Long id=draft();new TransactionTemplate(transactions).execute(s->{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->jdbc.update("UPDATE applications SET property_id=-999 WHERE application_id=?",id));s.setRollbackOnly();return null;});new TransactionTemplate(transactions).execute(s->{assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->jdbc.update("UPDATE applications SET applicant_id=? WHERE application_id=?",reviewer.id,id));s.setRollbackOnly();return null;});}
 @Test void paymentAttemptsRemainDistinctAndIssuanceIsRecorded(){Long id=draft();ready(id);service.payment(id,new PermitDtos.PaymentInput(BigDecimal.TEN,PaymentStatus.PENDING,null),finance);service.payment(id,new PermitDtos.PaymentInput(BigDecimal.TEN,PaymentStatus.FAILED,"TEST-FAILED"),finance);var done=service.payment(id,new PermitDtos.PaymentInput(BigDecimal.TEN,PaymentStatus.SUCCESSFUL,"TEST-SUCCESS"),finance);assertEquals(3,done.payments().size());assertNotNull(done.issueDate());assertNotNull(done.processingTime());assertEquals(PermitStatus.PERMIT_ISSUED,done.status());assertEquals(applicant.id,done.payments().get(0).applicantId());assertEquals(0,BigDecimal.TEN.compareTo(done.totalFee()));}
 @Test void uploadDownloadUsesPersistentFilesAndEnforcesOwnership()throws Exception{Long id=draft();byte[] bytes="%PDF-1.4\nPersistent fixture".getBytes();mvc.perform(multipart("/api/documents").file(new MockMultipartFile("file","plan.pdf","application/pdf",bytes)).param("applicationId",id.toString()).with(csrf()).with(user("applicant").roles("APPLICANT")).requestAttr("currentUser",applicant)).andExpect(status().isOk());var d=documents.findByApplicationIdOrderByUploadedAt(id).get(0);assertEquals("",d.contentBase64);assertNotNull(d.filePath);mvc.perform(get("/api/documents/"+d.id).param("applicationId",id.toString()).with(user("applicant").roles("APPLICANT")).requestAttr("currentUser",applicant)).andExpect(status().isOk()).andExpect(content().bytes(bytes));AppUser other=fixture(Role.APPLICANT);mvc.perform(get("/api/documents/"+d.id).param("applicationId",id.toString()).with(user("other").roles("APPLICANT")).requestAttr("currentUser",other)).andExpect(status().isNotFound());}
 @Test void documentStoreReopensAfterAServiceRestart()throws Exception{Path root=Files.createTempDirectory("permitworks-persistence-");byte[] bytes="restart persistence".getBytes();String sha=java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(bytes));new DocumentStore(root.toString()).put(1L,sha,bytes);assertArrayEquals(bytes,new DocumentStore(root.toString()).read(1L,sha));assertThrows(IllegalArgumentException.class,()->new DocumentStore(root.toString()).read(1L,"../escape"));}
 @Test void dependentApplicationAndPropertyCreationRollBackTogether(){long before=properties.count();long apps=jdbc.queryForObject("SELECT count(*) FROM applications",Long.class);assertThrows(IllegalStateException.class,()->new TransactionTemplate(transactions).execute(s->{draft();throw new IllegalStateException("Deliberate rollback fixture");}));assertEquals(before,properties.count());assertEquals(apps,jdbc.queryForObject("SELECT count(*) FROM applications",Long.class));}
 @Test void adminCanAssignAndDecideWithMatchingFrontendActions(){AppUser admin=users.findByEmail("admin@permitworks.com").orElseThrow();Long id=draft();service.submit(id,applicant);assertTrue(service.get(id,admin).availableActions().contains("VERIFY_DOCUMENTS"));service.verifyDocuments(id,new PermitDtos.DocumentDecision(true,"Admin verified"),admin);assertTrue(service.get(id,admin).availableActions().contains("ASSIGN_REVIEWERS"));service.assign(id,new PermitDtos.AssignmentInput(AssignmentType.PERMIT_REVIEWER,reviewer.id),admin);service.assign(id,new PermitDtos.AssignmentInput(AssignmentType.ZONING_OFFICER,zoning.id),admin);service.review(id,ReviewType.TECHNICAL,new PermitDtos.ReviewInput(ReviewRecommendation.APPROVE,"Reviewed"),reviewer);service.review(id,ReviewType.ZONING,new PermitDtos.ReviewInput(ReviewRecommendation.APPROVE,"Reviewed"),zoning);assertTrue(service.get(id,admin).availableActions().contains("FINAL_DECISION"));assertEquals(PermitStatus.APPROVED,service.decide(id,new PermitDtos.DecisionInput("APPROVE","Admin approved"),admin).status());}
 @Test void correctionResourceChecksRoleAndPersistsTheRequest()throws Exception{Long id=draft();service.submit(id,applicant);String body="{\"applicationId\":"+id+",\"description\":\"Please clarify the drawing\"}";mvc.perform(post("/api/corrections").contentType("application/json").content(body).with(csrf()).with(user("applicant").roles("APPLICANT")).requestAttr("currentUser",applicant)).andExpect(status().isForbidden());mvc.perform(post("/api/corrections").contentType("application/json").content(body).with(csrf()).with(user("department").roles("DEPARTMENT_OFFICER")).requestAttr("currentUser",department)).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("CORRECTION_REQUIRED"));assertEquals(department.id,jdbc.queryForObject("SELECT officer_id FROM corrections WHERE application_id=?",Long.class,id));}
}
